/* Select the strongest populated level separately for each required event house. */
(()=>{'use strict';const fields=method=>method==='sixfold'?['A','B','C','D','E','F']:['A','B','C','D'];function firstAvailable(row,method='fourfold'){for(const level of fields(method)){const planets=[...new Set((Array.isArray(row?.[level])?row[level]:[]).filter(id=>typeof id==='string'&&id))];if(planets.length)return {level,planets};}return {level:null,planets:[]};}function select(model,required,method='fourfold'){const data=model?.[method==='sixfold'?'sixfold':'fourfold'];const result=new Map();for(const house of [...new Set(required)]){const row=data?.houses?.find(r=>Number(r.id)===Number(house));if(!row)continue;const chosen=firstAvailable(row,method);for(const id of chosen.planets){if(!result.has(id))result.set(id,{id,houses:[],sourceHouses:[],levels:{}});const entry=result.get(id);entry.houses.push(Number(house));entry.sourceHouses.push(Number(house));entry.levels[house]=chosen.level;}}return [...result.values()].map(row=>({...row,houses:row.houses.sort((a,b)=>a-b),level:[...new Set(Object.values(row.levels))].join('/')}));}function render(){if(typeof document==='undefined')return;const card=document.querySelector('#transit .tr-card');if(!card)return;let box=document.getElementById('tr-selected-significators');if(!box){box=document.createElement('section');box.id='tr-selected-significators';box.className='tr-significators-summary';box.setAttribute('aria-label','Selected event significators');box.setAttribute('data-no-localize','');card.append(box);}box.replaceChildren();try{const rows=window.KPTransit.significators(),mr=window.KPPreferences?.get().language==='marathi',title=document.createElement('strong');title.textContent=mr?'घटना कार्येश':'Event significators';box.append(title);for(const row of rows){const chip=document.createElement('span');chip.dataset.significator=row.id;chip.textContent=(window.KPPlanetNotation?.label(row.id,window.KPPreferences?.get().language)||row.id)+' · '+(mr?'भाव ':'houses ')+row.houses.join(', ');chip.title=Object.entries(row.levels).map(([house,level])=>'House '+house+' · Level '+level).join('; ');box.append(chip);}if(!rows.length)box.append(document.createTextNode(mr?'निवडलेल्या भावांसाठी कार्येश नाहीत.':'No significators for the selected event houses.'));}catch(error){box.textContent=error.message;}}let timer;function schedule(){clearTimeout(timer);timer=setTimeout(render,40);}if(typeof document!=='undefined'){const init=()=>{schedule();document.addEventListener('change',event=>{if(event.target.closest?.('#transit'))schedule();});document.addEventListener('click',event=>{if(event.target.closest?.('[data-tr-search-mode],#manual-transit-open,[data-tab="transit"]'))schedule();});for(const event of ['chart-saved','chart-manual-change','kp-preferences-changed'])window.addEventListener(event,schedule);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,500));else setTimeout(init,500);}window.KPTransitSignificators=Object.freeze({firstAvailable,select,render});})();
